#!/usr/bin/env python3
from pathlib import Path
import json,base64,hashlib
ROOT=Path(__file__).resolve().parents[1];CAST=ROOT/'Design/Voices/VoiceCasting';OUT=ROOT/'Verification/SelectedEnginePilot'
def data(p,mime):return 'data:'+mime+';base64,'+base64.b64encode(p.read_bytes()).decode()
a=json.loads((CAST/'approved-choices.json').read_text());m=json.loads((OUT/'manifest.json').read_text());items=[]
for c,v in a['selectedVoices'].items():
 items.append({'id':c,'name':c.title(),'voice':v['name'],'image':data(CAST/'images'/f'{c}.png','image/png'),'original':data(CAST/'audio'/f'{v["voice"]}.m4a','audio/mp4'),'originalText':a['auditionText'],'text':m['text'],'direct':data(OUT/c/'direct.m4a','audio/mp4'),'reference':data(OUT/c/'reference.m4a','audio/mp4'),'hashes':{route:m['clips'][f'{c}/{route}']['audioSHA256'] for route in ['direct','reference']}})
payload=json.dumps(items).replace('</','<\\/');choices_hash=hashlib.sha256((CAST/'approved-choices.json').read_bytes()).hexdigest()
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tick & Kin · Voice repair pilot</title><style>*{box-sizing:border-box}body{margin:0;background:#f7f4ed;color:#263e43;font:16px/1.5 system-ui}main{max-width:1150px;margin:auto;padding:32px 24px}h1{font:38px Georgia;margin:8px 0}h2{margin:0}p{color:#617476}button{font:inherit;color:inherit;border:1px solid #d9d6ca;border-radius:12px;background:#fffdf8;padding:10px 16px;cursor:pointer}button.active{background:#d8e9e1;border-color:#376c63}.rail{display:flex;gap:8px;overflow:auto;margin:24px 0}.rail button{flex:0 0 78px;padding:8px}.rail img{width:48px;height:48px;object-fit:contain;display:block;margin:auto}.summary{display:flex;justify-content:space-between;gap:20px;align-items:center}article{background:#fffdf9;padding:24px;border:1px solid #dedbce;border-radius:22px}.head{display:flex;gap:24px;align-items:center}.head img{width:150px;height:150px;object-fit:contain;image-rendering:pixelated}.samples{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}.sample{background:#f4f1e8;border-radius:16px;padding:18px}h3{margin:0;font-size:18px}.sample p{min-height:90px;font-size:14px}audio{width:100%;margin-bottom:14px}.pick{width:100%}textarea{font:inherit;width:100%;min-height:80px;border:1px solid #d9d6ca;border-radius:12px;padding:12px;margin-top:18px}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.hint{font-size:14px}#export{background:#2b665e;color:white}@media(max-width:780px){.samples{grid-template-columns:1fr}.sample p{min-height:0}.head img{width:100px;height:100px}h1{font-size:30px}}</style><main><div class="summary"><div><small>TICK & KIN · VOICE REPAIR</small><h1>Keep the voice you chose.</h1></div><button id="export">Export review</button></div><p>The original A recording is the target. These two new samples test different generation methods using the original engine—not new character designs. Both say exactly the same words and have no speed or pitch changes.</p><p class="hint">“Reuse original voice” conditions the model on the original lossless A recording and its transcript. “Original design process” repeats the original model, description and seed for new words. Choose whichever preserves A’s voice without warbling. “Neither” is valid.</p><nav class="rail" id="rail"></nav><article id="card"></article><div class="actions"><button id="prev">← Previous</button><button id="next">Next →</button><button id="all">Use “Reuse original voice” for all</button><span id="progress"></span></div><p class="hint">All audio and character images are embedded. No server needed. Choices stay in this browser until exported. This is a pilot review; the app bundle has not been replaced.</p></main><script>const items=PAYLOAD,choicesHash="CHOICES_HASH",key="tick-kin-engine-pilot-v2";let state={};try{state=JSON.parse(localStorage.getItem(key)||"{}")}catch{}let index=0;const $=s=>document.querySelector(s);function stop(){document.querySelectorAll('audio').forEach(a=>a.pause())}function save(){localStorage.setItem(key,JSON.stringify(state))}function pick(route){let c=items[index];state[c.id]={route,status:route==='neither'?'rejected':'approved',pilotSHA256:c.hashes[route]||null,note:state[c.id]?.note||''};save();draw()}function draw(){stop();let c=items[index],choice=state[c.id]?.route;$('#rail').innerHTML=items.map((x,i)=>`<button data-index="${i}" class="${i===index?'active':''}"><img src="${x.image}" alt="">${x.name}${state[x.id]?.status==='approved'?' ✓':''}</button>`).join('');$('#rail').querySelectorAll('button').forEach(b=>b.onclick=()=>{index=+b.dataset.index;draw()});$('#card').innerHTML=`<div class="head"><img src="${c.image}" alt="${c.name}"><div><h2>${c.name}</h2><p>${c.voice}</p></div></div><div class="samples"><section class="sample"><h3>Original A · your choice</h3><p>${c.originalText}</p><audio controls preload="none" src="${c.original}"></audio></section><section class="sample"><h3>Reuse original voice</h3><p>${c.text}</p><audio controls preload="none" src="${c.reference}"></audio><button class="pick ${choice==='reference'?'active':''}" id="reference">${choice==='reference'?'✓ Selected':'This matches A'}</button></section><section class="sample"><h3>Original design process</h3><p>${c.text}</p><audio controls preload="none" src="${c.direct}"></audio><button class="pick ${choice==='direct'?'active':''}" id="direct">${choice==='direct'?'✓ Selected':'This matches A'}</button></section></div><textarea id="note" placeholder="Any warbling, unclear words, or a different-sounding character?"></textarea><div class="actions"><button id="neither" class="${choice==='neither'?'active':''}">Neither sounds right</button><button id="clear">Clear choice</button></div>`;$('#reference').onclick=()=>pick('reference');$('#direct').onclick=()=>pick('direct');$('#neither').onclick=()=>pick('neither');$('#clear').onclick=()=>{delete state[c.id];save();draw()};$('#note').value=state[c.id]?.note||'';$('#note').oninput=e=>{state[c.id]={...state[c.id],note:e.target.value};save()};$('#progress').textContent=Object.values(state).filter(x=>x.status==='approved').length+' / 12 accepted';$('#prev').disabled=index===0;$('#next').disabled=index===items.length-1}$('#prev').onclick=()=>{index=Math.max(0,index-1);draw()};$('#next').onclick=()=>{index=Math.min(items.length-1,index+1);draw()};$('#all').onclick=()=>{items.forEach(c=>state[c.id]={route:'reference',status:'approved',pilotSHA256:c.hashes.reference,note:state[c.id]?.note||''});save();draw()};$('#export').onclick=()=>{let blob=new Blob([JSON.stringify({version:2,choicesSHA256:choicesHash,routes:state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='tick-and-kin-engine-review.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};document.addEventListener('play',e=>{if(e.target.tagName==='AUDIO')document.querySelectorAll('audio').forEach(a=>{if(a!==e.target)a.pause()})},true);draw();</script></html>'''.replace('PAYLOAD',payload).replace('CHOICES_HASH',choices_hash)
p=OUT/'index.html';p.write_text(page);print(p,round(p.stat().st_size/1024/1024,1),'MB')
